// --- THE ULTIMATE INTERVIEW QUESTION ---
// Can you predict the order?

console.log('1. Start');

setTimeout(() => {
  console.log('5. setTimeout 1');
  Promise.resolve().then(() => console.log('6. Promise inside setTimeout'));
}, 0);

Promise.resolve().then(() => {
  console.log('4. Promise 1');
  setTimeout(() => console.log('8. setTimeout inside Promise'), 0);
});

process.nextTick(() => {
  console.log('3. nextTick 1');
});

setTimeout(() => {
  console.log('7. setTimeout 2');
}, 0);

console.log('2. End');

/*
  THE ANSWER:
  1. Start (Sync code)
  2. End (Sync code)
  3. nextTick 1 (Highest priority microtask)
  4. Promise 1 (Standard microtask)
  --- Microtasks are empty, Event Loop begins Timers Phase! ---
  5. setTimeout 1 (First timer)
  6. Promise inside setTimeout (Wait! Microtask created! Event loop pauses to run it!)
  7. setTimeout 2 (Next timer)
  8. setTimeout inside Promise (Queued later)
*/
